#!/usr/bin/env python3
"""Scanner: walk project folders → build description cache for executor context."""

import json
import subprocess
import time
from pathlib import Path

CACHE_PATH = Path.home() / ".arc-dispatch" / "project_cache.json"
MAP_PATH = Path(__file__).parent / "project_map.json"

# Files/dirs that reveal project tech stack and structure
INTEREST_FILES = [
    "package.json", "package-lock.json", "yarn.lock", "pnpm-lock.yaml",
    "tsconfig.json", "vite.config.ts", "vite.config.js",
    "README.md", "README.zh.md",
    "pyproject.toml", "setup.py", "requirements.txt",
    "Cargo.toml", "go.mod",
    "AndroidManifest.xml", "build.gradle", "build.gradle.kts",
    "CLAUDE.md", ".claude/CLAUDE.md",
]

# Directories to enumerate (one level deep)
INTEREST_DIRS = ["src", "lib", "app", "pages", "components", "api", "store", "utils"]

MAX_FILE_BYTES = 8_000  # truncate large files


def _read_truncated(path: Path) -> str:
    try:
        text = path.read_text(errors="replace")
        if len(text) > MAX_FILE_BYTES:
            text = text[:MAX_FILE_BYTES] + "\n...[truncated]"
        return text
    except Exception:
        return ""


def _list_dir(path: Path) -> list[str]:
    try:
        return sorted(p.name for p in path.iterdir())
    except Exception:
        return []


def _src_tree(project_path: Path) -> str:
    """Return compact directory tree for src-like dirs."""
    lines = []
    for dname in INTEREST_DIRS:
        d = project_path / dname
        if not d.is_dir():
            continue
        entries = _list_dir(d)
        lines.append(f"{dname}/")
        for e in entries[:30]:
            sub = d / e
            if sub.is_dir():
                children = _list_dir(sub)
                lines.append(f"  {e}/  [{len(children)} items]")
            else:
                lines.append(f"  {e}")
        if len(entries) > 30:
            lines.append(f"  ... ({len(entries) - 30} more)")
    return "\n".join(lines)


def _root_files(project_path: Path) -> list[str]:
    try:
        return sorted(
            p.name for p in project_path.iterdir()
            if p.is_file() and not p.name.startswith(".")
        )
    except Exception:
        return []


def scan_project(project_id: str, project_path: str) -> dict:
    """Scan one project folder and return a cache entry."""
    p = Path(project_path)
    if not p.is_dir():
        return {
            "project_id": project_id,
            "project_path": project_path,
            "exists": False,
            "scanned_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }

    interest_contents = {}
    for fname in INTEREST_FILES:
        fpath = p / fname
        if fpath.is_file():
            interest_contents[fname] = _read_truncated(fpath)

    # Parse package.json for quick stack summary
    stack_summary = ""
    if "package.json" in interest_contents:
        try:
            pkg = json.loads(interest_contents["package.json"])
            deps = list((pkg.get("dependencies") or {}).keys())
            dev_deps = list((pkg.get("devDependencies") or {}).keys())
            name = pkg.get("name", "")
            scripts = list((pkg.get("scripts") or {}).keys())
            stack_summary = (
                f"name={name} "
                f"deps=[{', '.join(deps[:10])}{'...' if len(deps)>10 else ''}] "
                f"devDeps=[{', '.join(dev_deps[:10])}{'...' if len(dev_deps)>10 else ''}] "
                f"scripts=[{', '.join(scripts)}]"
            )
        except Exception:
            pass

    return {
        "project_id": project_id,
        "project_path": project_path,
        "exists": True,
        "scanned_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "stack_summary": stack_summary,
        "root_files": _root_files(p),
        "src_tree": _src_tree(p),
        "interest_files": interest_contents,
    }


def scan_all(force: bool = False) -> dict:
    """Scan all projects in project_map.json. Returns full cache dict."""
    pmap = json.loads(MAP_PATH.read_text())

    # Load existing cache
    cache: dict = {}
    if CACHE_PATH.is_file() and not force:
        try:
            cache = json.loads(CACHE_PATH.read_text())
        except Exception:
            cache = {}

    for project in pmap["projects"]:
        pid = project["id"]
        ppath = project["project_path"]

        # Skip if recently scanned (< 1 hour) unless forced
        existing = cache.get(pid, {})
        if not force and existing.get("scanned_at"):
            age = time.time() - time.mktime(time.strptime(existing["scanned_at"], "%Y-%m-%dT%H:%M:%SZ"))
            if age < 3600:
                print(f"  [skip] {pid} — cached {int(age/60)}m ago")
                continue

        print(f"  [scan] {pid} → {ppath}")
        entry = scan_project(pid, ppath)
        cache[pid] = entry
        _write_hermes_md(entry)

    CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
    CACHE_PATH.write_text(json.dumps(cache, ensure_ascii=False, indent=2))
    print(f"[scanner] Cache written → {CACHE_PATH}")
    return cache


def _write_hermes_md(entry: dict) -> None:
    """Write .hermes.md into project root so Hermes auto-loads it as context."""
    if not entry.get("exists"):
        return
    ctx = _entry_to_context(entry)
    if not ctx:
        return
    hermes_md = Path(entry["project_path"]) / ".hermes.md"
    hermes_md.write_text(
        f"<!-- Auto-generated by arc-dispatch scanner. Do not edit manually. -->\n\n{ctx}\n",
        encoding="utf-8",
    )
    print(f"    [.hermes.md] written → {hermes_md}")


def _entry_to_context(entry: dict) -> str:
    """Build context string from a cache entry dict (no file I/O)."""
    if not entry or not entry.get("exists"):
        return ""
    parts = [f"## Project: {entry['project_id']}  ({entry['project_path']})"]
    if entry.get("stack_summary"):
        parts.append(f"**Stack:** {entry['stack_summary']}")
    if entry.get("src_tree"):
        parts.append("**Source tree:**\n```\n" + entry["src_tree"] + "\n```")
    ifiles = entry.get("interest_files", {})
    for fname in [".claude/CLAUDE.md", "CLAUDE.md", "README.md", "README.zh.md"]:
        if fname in ifiles and ifiles[fname].strip():
            parts.append(f"**{fname}:**\n```\n{ifiles[fname][:3000]}\n```")
            break
    return "\n\n".join(parts)


def get_context(project_id: str) -> str:
    """
    Return a compact context string for a project, ready for prompt injection.
    Loads from cache (does NOT trigger scan).
    """
    if not CACHE_PATH.is_file():
        return ""
    try:
        cache = json.loads(CACHE_PATH.read_text())
    except Exception:
        return ""

    return _entry_to_context(cache.get(project_id))


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description="Scan project folders and build description cache")
    parser.add_argument("--force", action="store_true", help="Re-scan even if recently cached")
    parser.add_argument("--project", help="Scan single project by ID only")
    parser.add_argument("--show", help="Print cached context for a project ID")
    args = parser.parse_args()

    if args.show:
        ctx = get_context(args.show)
        print(ctx if ctx else f"[no cache for {args.show}]")
    elif args.project:
        pmap = json.loads(MAP_PATH.read_text())
        proj = next((p for p in pmap["projects"] if p["id"] == args.project), None)
        if not proj:
            print(f"Unknown project id: {args.project}")
        else:
            entry = scan_project(args.project, proj["project_path"])
            CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
            cache = {}
            if CACHE_PATH.is_file():
                try:
                    cache = json.loads(CACHE_PATH.read_text())
                except Exception:
                    pass
            cache[args.project] = entry
            CACHE_PATH.write_text(json.dumps(cache, ensure_ascii=False, indent=2))
            print(json.dumps(entry, ensure_ascii=False, indent=2))
    else:
        print("[scanner] Scanning all projects...")
        scan_all(force=args.force)


