#!/usr/bin/env python3
"""Executor: run claude CLI against PENDING TASK envelopes."""

import json
import subprocess
import sys
from pathlib import Path

import db
import scanner


def _build_prompt(envelope: dict) -> str:
    payload = envelope["payload"]
    summary = payload.get("summary", "")
    description = payload.get("description", "")
    project_id = payload.get("project_id", "")
    reference_path = payload.get("reference_path")

    parts = []

    # Project context from cache
    ctx = scanner.get_context(project_id)
    if ctx:
        parts.append(ctx)

    # Reference project context (android read-only)
    if reference_path:
        ref_id = None
        try:
            import json as _json
            pmap = _json.loads((Path(__file__).parent / "project_map.json").read_text())
            ref_id = next(
                (p["id"] for p in pmap["projects"] if p["project_path"] == reference_path),
                None,
            )
        except Exception:
            pass
        if ref_id:
            ref_ctx = scanner.get_context(ref_id)
            if ref_ctx:
                parts.append(
                    f"## Reference (read-only, do NOT modify): {reference_path}\n\n{ref_ctx}"
                )
        parts.append(
            f"IMPORTANT: The Android codebase at `{reference_path}` is for REFERENCE ONLY. "
            "Do not edit any files there. Mirror the relevant logic in the current project."
        )

    # Task
    parts.append(f"## Task\n\n{summary}")
    if description and description.strip():
        parts.append(f"### Details\n\n{description.strip()}")

    return "\n\n---\n\n".join(parts)


def execute_one(envelope: dict, dry_run: bool = False) -> dict:
    """
    Run claude on a single TASK envelope.
    Returns updated envelope (fetched fresh from DB after execution).
    """
    eid = envelope["id"]
    project_path = envelope["project"]
    payload = envelope["payload"]
    summary = payload.get("summary", "")[:60]

    print(f"[executor] {eid[:8]} — {summary}")

    prompt = _build_prompt(envelope)

    if dry_run:
        print(f"  [DRY] cwd={project_path}")
        print(f"  [DRY] prompt preview ({len(prompt)} chars):")
        print("  " + prompt[:300].replace("\n", "\n  "))
        return envelope

    db.update_status(eid, "RUNNING")
    db.append_trace(eid, {"event": "executor_start", "project": project_path})

    try:
        result = subprocess.run(
            ["claude", "--print", "--permission-mode", "bypassPermissions"],
            input=prompt,
            capture_output=True,
            text=True,
            cwd=project_path,
            timeout=600,
        )

        stdout = result.stdout.strip()
        stderr = result.stderr.strip()

        db.append_trace(eid, {
            "event": "executor_done",
            "returncode": result.returncode,
            "stdout_len": len(stdout),
            "stderr_preview": stderr[:500] if stderr else None,
        })

        if result.returncode != 0:
            db.update_status(eid, "FAILED", error=stderr[:1000])
            print(f"  [FAIL] rc={result.returncode} {stderr[:120]}")
        else:
            # Store output in payload for validator
            existing = db.get(eid)
            new_payload = {**existing["payload"], "executor_output": stdout}
            db.set_payload(eid, new_payload)
            db.update_status(eid, "DONE")
            print(f"  [OK] {len(stdout)} chars output")

    except subprocess.TimeoutExpired:
        db.update_status(eid, "FAILED", error="timeout 600s")
        db.append_trace(eid, {"event": "timeout"})
        print(f"  [FAIL] timeout")
    except Exception as e:
        db.update_status(eid, "FAILED", error=str(e))
        print(f"  [FAIL] {e}")

    return db.get(eid)


def execute_all(dry_run: bool = False, limit: int = 0) -> list[dict]:
    """Process all PENDING TASK envelopes."""
    pending = db.list_pending(type="TASK")
    print(f"[executor] {len(pending)} pending tasks")

    if limit:
        pending = pending[:limit]

    results = []
    for env in pending:
        r = execute_one(env, dry_run=dry_run)
        results.append(r)

    return results


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--limit", type=int, default=0, help="Max tasks to process (0=all)")
    parser.add_argument("--id", help="Execute single envelope by ID prefix")
    args = parser.parse_args()

    if args.id:
        all_envs = db.list_all(limit=500)
        match = next((e for e in all_envs if e["id"].startswith(args.id)), None)
        if not match:
            print(f"No envelope matching id prefix: {args.id}")
            sys.exit(1)
        execute_one(match, dry_run=args.dry_run)
    else:
        execute_all(dry_run=args.dry_run, limit=args.limit)


