#!/usr/bin/env python3
"""Collector: pull pending tasks from Lark Task Center → TASK envelopes."""

import json
import sys
import time
from pathlib import Path

import db
import router

# ── Lark token ────────────────────────────────────────────────────────────────

def _get_token() -> str:
    """Read user_access_token from lark-mcp storage."""
    import subprocess
    LARK_MCP_ROOT = "/Users/charles/.nvm/versions/node/v24.14.0/lib/node_modules/@larksuiteoapi/lark-mcp"
    script = f"""
const {{ authStore }} = require('{LARK_MCP_ROOT}/dist/auth/store.js');
authStore.initialize().then(() => {{
  const tokens = authStore.storageDataCache.tokens || {{}};
  const keys = Object.keys(tokens);
  if (!keys.length) {{ process.stderr.write('NO_TOKEN\\n'); process.exit(1); }}
  const token = keys[0];
  const meta = tokens[token];
  if (Date.now() / 1000 > meta.expiresAt) {{ process.stderr.write('TOKEN_EXPIRED\\n'); process.exit(1); }}
  process.stdout.write(token);
  process.exit(0);
}}).catch(e => {{ process.stderr.write(String(e)); process.exit(1); }});
"""
    result = subprocess.run(
        ["node", "-e", script],
        capture_output=True, text=True, timeout=15
    )
    if result.returncode != 0:
        raise RuntimeError(f"Token error: {result.stderr.strip()}")
    return result.stdout.strip()


# ── Lark API ───────────────────────────────────────────────────────────────────

def _fetch_tasks(token: str, page_size: int = 100) -> list[dict]:
    """Fetch all incomplete tasks for current user (paginated)."""
    import urllib.request
    items = []
    page_token = None

    while True:
        url = f"https://open.larksuite.com/open-apis/task/v2/tasks?page_size={page_size}&completed=false"
        if page_token:
            url += f"&page_token={page_token}"
        req = urllib.request.Request(url, headers={"Authorization": f"Bearer {token}"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read())

        if data.get("code") != 0:
            raise RuntimeError(f"Lark API error {data.get('code')}: {data.get('msg')}")

        items.extend(data.get("data", {}).get("items", []))
        if not data.get("data", {}).get("has_more"):
            break
        page_token = data["data"]["page_token"]

    return items


# ── Filter ─────────────────────────────────────────────────────────────────────

def _should_dispatch(task: dict) -> bool:
    """
    Include task if:
      1. Not completed (completed_at == "0")
      2. No 状态 custom field (treat as unprocessed)

    Exclude if 状态 field exists (any value = already tracked or handled).
    Update UNMODIFIED_GUIDS when option GUIDs are confirmed.
    """
    if task.get("completed_at", "0") != "0":
        return False

    for cf in task.get("custom_fields", []):
        if cf.get("name") == "状态":
            # Has status field → skip (handled or in-progress)
            # TODO: once GUID confirmed, change to:
            # return UNMODIFIED_GUID in cf.get("multi_select_value", [])
            return False

    return True


# ── Dedup ──────────────────────────────────────────────────────────────────────

def _already_enqueued(task_guid: str) -> bool:
    """Skip tasks already in envelopes DB (any status)."""
    existing = db.list_all(limit=500)
    return any(
        e["payload"].get("lark_task_guid") == task_guid
        for e in existing
    )


# ── Main ───────────────────────────────────────────────────────────────────────

def collect(dry_run: bool = False) -> list[dict]:
    """
    Pull pending Lark tasks → create TASK envelopes.
    Router resolves project_path per task summary.

    Returns:
        list of created envelopes
    """
    print("[collector] Fetching token...")
    token = _get_token()

    print("[collector] Fetching tasks from Lark...")
    tasks = _fetch_tasks(token)
    print(f"[collector] Got {len(tasks)} incomplete tasks")

    candidates = [t for t in tasks if _should_dispatch(t)]
    print(f"[collector] {len(candidates)} match filter (no 状态 field)")

    created = []
    skipped = 0

    for task in candidates:
        guid = task["guid"]

        if _already_enqueued(guid):
            skipped += 1
            continue

        summary = task.get("summary", "")
        routes = router.resolve(summary)

        base_payload = {
            "lark_task_guid": guid,
            "summary": summary,
            "description": task.get("description", ""),
            "custom_fields": task.get("custom_fields", []),
            "members": task.get("members", []),
            "lark_url": task.get("url", ""),
            "collected_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }

        for route in routes:
            payload = {
                **base_payload,
                "project_id": route["project_id"],
                "reference_path": route["reference_path"],
            }
            if dry_run:
