#!/usr/bin/env python3
"""Router: resolve task summary → project_path using project_map.json."""

import json
from pathlib import Path

_MAP_PATH = Path(__file__).parent / "project_map.json"
_map: dict | None = None


def _load() -> dict:
    global _map
    if _map is None:
        _map = json.loads(_MAP_PATH.read_text())
    return _map


def resolve(summary: str) -> list[dict]:
    """
    Match task summary against project_map keywords.

    Returns list of route dicts (fan-out for multi-project tasks):
        [
            {
                "project_path": "/abs/path/to/execute/in",
                "reference_path": "/abs/path/to/read/only" | None,
                "project_id": "web_ui",
            },
            ...
        ]
    Single-project tasks return a list of one element.
    """
    pmap = _load()
    projects = pmap["projects"]
    s = summary.lower()

    matched = None
    for p in projects:
        if not p.get("keywords"):
            continue
        if any(k.lower() in s for k in p["keywords"]):
            matched = p
            break

    if matched is None:
        matched = next(p for p in projects if p["id"] == "default")

    reference_path = None

    if matched.get("reference_only"):
        reference_path = matched["project_path"]
        route_to_id = matched.get("route_to", "default")
        matched = next(p for p in projects if p["id"] == route_to_id)

    # Fan-out: multi-project (e.g. 三端 → web_ui + uaec_h5)
    if matched.get("exec_projects"):
        routes = []
        for pid in matched["exec_projects"]:
            target = next(p for p in projects if p["id"] == pid)
            routes.append({
                "project_path": target["project_path"],
                "reference_path": reference_path,
                "project_id": target["id"],
            })
        return routes

    return [{
        "project_path": matched["project_path"],
        "reference_path": reference_path,
        "project_id": matched["id"],
    }]


if __name__ == "__main__":
    import sys
    summary = " ".join(sys.argv[1:]) or "安卓端资产页面问题"
    result = resolve(summary)
    print(f"project_id:     {result['project_id']}")
    print(f"project_path:   {result['project_path']}")
    print(f"reference_path: {result['reference_path']}")


