#!/usr/bin/env python3
"""
Confirmer: lightweight LLM call to validate task understanding before execution.

Uses Hermes/Nous API (cheap, fast) — NOT Claude Code.
Filters out ambiguous/unexecutable tasks early.
"""

import json
import os
import re
import urllib.request
from pathlib import Path

import db
import scanner

# ── Hermes / Nous config ───────────────────────────────────────────────────────
# Reads from ~/.hermes/.env — same credentials Hermes uses

def _load_hermes_env() -> dict:
    env_path = Path.home() / ".hermes" / ".env"
    result = {}
    if env_path.is_file():
        for line in env_path.read_text().splitlines():
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, _, v = line.partition("=")
                result[k.strip()] = v.strip().strip('"').strip("'")
    return result

_hermes_env = _load_hermes_env()

# Prefer a cheap/fast model for confirmation (not Claude)
CONFIRM_MODEL = os.environ.get(
    "ARC_CONFIRM_MODEL",
    "qwen/qwen3-8b",          # fast, cheap, good at JSON
)
CONFIRM_API_BASE = os.environ.get(
    "ARC_CONFIRM_API_BASE",
    "https://openrouter.ai/api/v1",
)
CONFIRM_API_KEY = os.environ.get(
    "ARC_CONFIRM_API_KEY",
    _hermes_env.get("OPENROUTER_API_KEY", ""),
)

# ── Framework-specific hints ───────────────────────────────────────────────────

_FRAMEWORK_HINTS = {
    "web_ui": (
        "Vue 2 + Vuex + Element UI + Webpack. "
        "Pages in src/pages/, state in src/vuex/modules/. "
        "Asset pages under src/pages/Personal/. "
        "Route guard checks store.state.user.isLogin."
    ),
    "uaec_h5": (
        "Vue 2 + Vant + Vuex + Vue CLI (mobile H5). "
        "Views in src/views/ by feature (assets/, home/, mine/). "
        "Asset pages under src/views/assets/. "
        "Mobile-first rem layout, Vant component library."
    ),
    "uaec_android": (
        "Android (Kotlin/Java) — READ ONLY reference. "
        "Do not suggest modifying Android files. "
        "Use as behavioral reference for feature parity."
    ),
    "partner_ui": (
        "React + Umi 2 + DVA + Ant Design Pro. "
        "Convention-based routing: src/pages/ maps to routes. "
        "State via DVA models in src/models/ (dispatch with namespace prefix). "
        "Explicit routes also in config/router.config.js."
    ),
    "excloud_ui": (
        "React + Umi 2 + DVA + TypeScript + Ant Design. "
        "Same structure as partner-ui but fully typed. "
        "DVA models: cobber.ts (domain), global.ts, setting.ts. "
        "Type definitions in src/models/connect.d.ts."
    ),
    "all_platforms": (
        "Task spans web-ui (Vue 2) AND uaec-h5 (Vue 2 mobile). "
        "Both need changes. Android is reference only."
    ),
    "default": (
        "Vue 2 + Vuex + Element UI (web-ui project). "
        "Pages in src/pages/, state in src/vuex/modules/."
    ),
}

# ── Prompt ─────────────────────────────────────────────────────────────────────

_SYSTEM = """你是前端代码任务分析员。分析任务描述，判断是否可执行，输出 JSON。

规则：
- understood=false：任务依赖设计稿/后端接口/人工决策，无法直接执行
- risk=high：涉及认证、支付、合约交易逻辑
- action=unclear：任务描述含糊，无法确定改哪里

只输出 JSON，不要其他内容。"""

_USER_TMPL = """项目: {project_id}
框架: {framework_hint}

项目结构概览:
{context}

任务: {summary}

输出格式（严格 JSON）:
{{
  "understood": true,
  "action": "fix | feature | style | refactor | unclear",
  "scope": "具体涉及哪些文件或模块（如 src/pages/Personal/assets/index.vue）",
  "risk": "low | medium | high",
  "skip_reason": "若 understood=false 填写原因，否则为 null",
  "execution_hint": "给 Claude Code executor 的关键提示（框架模式、注意事项）"
}}"""

# ── API call ───────────────────────────────────────────────────────────────────

def _call_api(system: str, user: str) -> str:
    body = json.dumps({
        "model": CONFIRM_MODEL,
        "messages": [
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ],
        "temperature": 0.1,
        "max_tokens": 512,
    }).encode()

    req = urllib.request.Request(
        f"{CONFIRM_API_BASE}/chat/completions",
        data=body,
        headers={
            "Authorization": f"Bearer {CONFIRM_API_KEY}",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read())
    return data["choices"][0]["message"]["content"]


def _extract_json(text: str) -> dict:
    # Strip markdown code fences if present
    text = re.sub(r"```(?:json)?\s*", "", text).strip().rstrip("`").strip()
    # Find first {...}
    m = re.search(r"\{.*\}", text, re.DOTALL)
    if m:
        return json.loads(m.group())
    raise ValueError(f"No JSON in response: {text[:200]}")


# ── Main ───────────────────────────────────────────────────────────────────────

def confirm(envelope: dict, dry_run: bool = False) -> dict | None:
    """
    Validate one TASK envelope.
    Returns updated envelope if task is executable, None if skipped.
    """
    eid = envelope["id"]
    payload = envelope["payload"]
    summary = payload.get("summary", "")
    project_id = payload.get("project_id", "default")

    ctx = scanner.get_context(project_id)
    framework_hint = _FRAMEWORK_HINTS.get(project_id, _FRAMEWORK_HINTS["default"])

    user_msg = _USER_TMPL.format(
        project_id=project_id,
        framework_hint=framework_hint,
        context=ctx[:1500] if ctx else "(no cache — run scanner.py first)",
        summary=summary,
    )

    if dry_run:
        print(f"  [DRY confirmer] {eid[:8]} — {summary[:50]}")
        print(f"    project_id={project_id}")
        return envelope

    try:
        raw = _call_api(_SYSTEM, user_msg)
        plan = _extract_json(raw)
    except Exception as e:
        print(f"  [confirmer ERROR] {eid[:8]}: {e}")
        db.append_trace(eid, {"event": "confirm_error", "error": str(e)})
        return envelope  # don't block on confirmer failure

    understood = plan.get("understood", True)
    skip_reason = plan.get("skip_reason")

    db.append_trace(eid, {"event": "confirmed", "plan": plan})

    if not understood:
        db.update_status(eid, "FAILED", error=f"confirmer: {skip_reason}")
        print(f"  [SKIP] {eid[:8]} — {skip_reason}")
        return None

    # Inject plan into payload for executor
    new_payload = {**payload, "confirm_plan": plan}
    db.set_payload(eid, new_payload)
    print(
        f"  [OK] {eid[:8]} action={plan.get('action')} "
        f"risk={plan.get('risk')} scope={plan.get('scope','?')[:60]}"
    )
    return db.get(eid)


def confirm_all(dry_run: bool = False) -> tuple[list, list]:
    """Confirm all PENDING TASK envelopes. Returns (confirmed, skipped)."""
    pending = db.list_pending(type="TASK")
    print(f"[confirmer] {len(pending)} pending tasks")

    confirmed, skipped = [], []
    for env in pending:
        result = confirm(env, dry_run=dry_run)
        if result:
            confirmed.append(result)
        else:
            skipped.append(env)

    print(f"[confirmer] confirmed={len(confirmed)} skipped={len(skipped)}")
    return confirmed, skipped


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--id", help="Confirm single envelope by ID prefix")
    args = parser.parse_args()

    if args.id:
        all_envs = db.list_all(limit=500)
        match = next((e for e in all_envs if e["id"].startswith(args.id)), None)
        if not match:
            print(f"No envelope matching: {args.id}")
        else:
            confirm(match, dry_run=args.dry_run)
    else:
        confirm_all(dry_run=args.dry_run)


