#!/usr/bin/env python3
"""Reporter: write execution results back to Lark Task Center."""

import json
import time
import urllib.request
import urllib.error
from pathlib import Path

import db

LARK_MCP_ROOT = "/Users/charles/.nvm/versions/node/v24.14.0/lib/node_modules/@larksuiteoapi/lark-mcp"
LARK_API = "https://open.larksuite.com/open-apis"


def _get_token() -> str:
    import subprocess
    script = f"""
const {{ authStore }} = require('{LARK_MCP_ROOT}/dist/auth/store.js');
authStore.initialize().then(() => {{
  const tokens = authStore.storageDataCache.tokens || {{}};
  const keys = Object.keys(tokens);
  if (!keys.length) {{ process.stderr.write('NO_TOKEN\\n'); process.exit(1); }}
  const token = keys[0];
  const meta = tokens[token];
  if (Date.now() / 1000 > meta.expiresAt) {{ process.stderr.write('TOKEN_EXPIRED\\n'); process.exit(1); }}
  process.stdout.write(token);
  process.exit(0);
}}).catch(e => {{ process.stderr.write(String(e)); process.exit(1); }});
"""
    r = subprocess.run(["node", "-e", script], capture_output=True, text=True, timeout=15)
    if r.returncode != 0:
        raise RuntimeError(f"Token error: {r.stderr.strip()}")
    return r.stdout.strip()


def _api(token: str, method: str, path: str, body: dict | None = None) -> dict:
    url = f"{LARK_API}{path}"
    data = json.dumps(body).encode() if body else None
    req = urllib.request.Request(
        url,
        data=data,
        method=method,
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=15) as resp:
        return json.loads(resp.read())


def _add_comment(token: str, task_guid: str, content: str) -> bool:
    """Add a comment to a Lark task."""
    try:
        resp = _api(token, "POST", f"/task/v2/tasks/{task_guid}/comments", {
            "content": content,
        })
        return resp.get("code") == 0
    except Exception as e:
        print(f"    [comment error] {e}")
        return False


def _build_comment(envelope: dict) -> str:
    payload = envelope["payload"]
    status = envelope["status"]
    plan = payload.get("confirm_plan", {})
    output = payload.get("executor_output", "")
    validation = payload.get("validation", {})

    lines = [f"🤖 arc-dispatch 处理结果 — {time.strftime('%Y-%m-%d %H:%M UTC', time.gmtime())}"]
    lines.append(f"项目: {payload.get('project_id', '?')}  状态: {status}")

    if plan:
        lines.append(f"分析: action={plan.get('action')} risk={plan.get('risk')} scope={plan.get('scope','?')[:80]}")

    if validation:
        verdict = validation.get("verdict", "?")
        lines.append(f"验证: {verdict} — {validation.get('summary', '')[:120]}")

    if status == "DONE" and output:
        # First 300 chars of executor output as preview
        preview = output.strip()[:300].replace("\n", " ")
        lines.append(f"执行摘要: {preview}{'...' if len(output) > 300 else ''}")

    if status == "FAILED":
        lines.append(f"失败原因: {envelope.get('error', '未知')[:200]}")

    return "\n".join(lines)


def report(envelope: dict, dry_run: bool = False) -> bool:
    """Write back to Lark for one envelope. Returns True on success."""
    eid = envelope["id"]
    payload = envelope["payload"]
    task_guid = payload.get("lark_task_guid")

    if not task_guid:
        print(f"  [skip] {eid[:8]} — no lark_task_guid")
        return False

    comment = _build_comment(envelope)

    if dry_run:
        print(f"  [DRY reporter] {eid[:8]} → task {task_guid[:8]}")
        print("  " + comment.replace("\n", "\n  "))
        return True

    try:
        token = _get_token()
    except Exception as e:
        print(f"  [reporter] token error: {e}")
        return False

    ok = _add_comment(token, task_guid, comment)
    if ok:
        db.append_trace(eid, {"event": "reported", "lark_task_guid": task_guid})
        print(f"  [reported] {eid[:8]} → {task_guid[:8]}")
    else:
        print(f"  [report FAIL] {eid[:8]}")
    return ok


def report_done(dry_run: bool = False) -> list[dict]:
    """Report all DONE envelopes that haven't been reported yet."""
    with db._conn() as con:
        rows = con.execute(
            "SELECT * FROM envelopes WHERE status='DONE' ORDER BY updated_at"
        ).fetchall()
    envs = [db._row(r) for r in rows]

    # Filter: not yet reported (no 'reported' event in trace)
    pending_report = [
        e for e in envs
        if not any(t.get("event") == "reported" for t in e["trace"])
    ]
    print(f"[reporter] {len(pending_report)} done envelopes to report")

    results = []
    for env in pending_report:
        if report(env, dry_run=dry_run):
            results.append(env)

    return results


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--id", help="Report single envelope by ID prefix")
    args = parser.parse_args()

    if args.id:
        all_envs = db.list_all(limit=500)
        match = next((e for e in all_envs if e["id"].startswith(args.id)), None)
        if not match:
            print(f"No envelope matching: {args.id}")
        else:
            report(match, dry_run=args.dry_run)
    else:
        report_done(dry_run=args.dry_run)


