#!/usr/bin/env python3
"""SQLite envelopes message bus."""

import json
import sqlite3
import uuid
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional

DB_PATH = Path.home() / ".arc-dispatch" / "envelopes.db"

SCHEMA = """
CREATE TABLE IF NOT EXISTS envelopes (
    id          TEXT PRIMARY KEY,
    type        TEXT NOT NULL CHECK(type IN ('TASK','PLAN','RESULT','VALIDATION')),
    status      TEXT NOT NULL CHECK(status IN ('PENDING','RUNNING','DONE','FAILED')) DEFAULT 'PENDING',
    project     TEXT NOT NULL,
    payload     TEXT NOT NULL DEFAULT '{}',
    trace       TEXT NOT NULL DEFAULT '[]',
    error       TEXT,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_status ON envelopes(status);
CREATE INDEX IF NOT EXISTS idx_type   ON envelopes(type);
CREATE INDEX IF NOT EXISTS idx_project ON envelopes(project);
"""


@contextmanager
def _conn():
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(str(DB_PATH))
    con.row_factory = sqlite3.Row
    try:
        con.executescript(SCHEMA)
        yield con
        con.commit()
    finally:
        con.close()


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _row(row) -> dict:
    d = dict(row)
    d["payload"] = json.loads(d["payload"])
    d["trace"] = json.loads(d["trace"])
    return d


# ── Write ──────────────────────────────────────────────────────────────────────

def create(type: str, project: str, payload: dict, envelope_id: Optional[str] = None) -> dict:
    now = _now()
    env = {
        "id": envelope_id or str(uuid.uuid4()),
        "type": type,
        "status": "PENDING",
        "project": project,
        "payload": payload,
        "trace": [],
        "error": None,
        "created_at": now,
        "updated_at": now,
    }
    with _conn() as con:
        con.execute(
            "INSERT INTO envelopes VALUES (?,?,?,?,?,?,?,?,?)",
            (env["id"], env["type"], env["status"], env["project"],
             json.dumps(env["payload"]), json.dumps(env["trace"]),
             env["error"], env["created_at"], env["updated_at"]),
        )
    return env


def update_status(eid: str, status: str, error: Optional[str] = None) -> None:
    with _conn() as con:
        con.execute(
            "UPDATE envelopes SET status=?, error=?, updated_at=? WHERE id=?",
            (status, error, _now(), eid),
        )


def append_trace(eid: str, entry: Any) -> None:
    with _conn() as con:
        row = con.execute("SELECT trace FROM envelopes WHERE id=?", (eid,)).fetchone()
        if not row:
            raise KeyError(eid)
        trace = json.loads(row["trace"])
        if isinstance(entry, dict):
            trace.append({"ts": _now(), **entry})
        else:
            trace.append({"ts": _now(), "msg": str(entry)})
        con.execute(
            "UPDATE envelopes SET trace=?, updated_at=? WHERE id=?",
            (json.dumps(trace), _now(), eid),
        )


def set_payload(eid: str, payload: dict) -> None:
    with _conn() as con:
        con.execute(
            "UPDATE envelopes SET payload=?, updated_at=? WHERE id=?",
            (json.dumps(payload), _now(), eid),
        )


# ── Read ───────────────────────────────────────────────────────────────────────

def get(eid: str) -> Optional[dict]:
    with _conn() as con:
        row = con.execute("SELECT * FROM envelopes WHERE id=?", (eid,)).fetchone()
        return _row(row) if row else None


def list_pending(type: Optional[str] = None) -> list:
    with _conn() as con:
        if type:
            rows = con.execute(
                "SELECT * FROM envelopes WHERE status='PENDING' AND type=? ORDER BY created_at",
                (type,),
            ).fetchall()
        else:
            rows = con.execute(
                "SELECT * FROM envelopes WHERE status='PENDING' ORDER BY created_at"
            ).fetchall()
        return [_row(r) for r in rows]


def list_all(limit: int = 50) -> list:
    with _conn() as con:
        rows = con.execute(
            "SELECT * FROM envelopes ORDER BY created_at DESC LIMIT ?", (limit,)
        ).fetchall()
        return [_row(r) for r in rows]


if __name__ == "__main__":
    import sys
    cmd = sys.argv[1] if len(sys.argv) > 1 else "list"
    if cmd == "list":
        for e in list_all():
            print(f"{e['id'][:8]}  {e['type']:10} {e['status']:8} {e['project']}")
    elif cmd == "get" and len(sys.argv) > 2:
        print(json.dumps(get(sys.argv[2]), indent=2))
    elif cmd == "init":
        with _conn():
            pass
        print(f"DB initialized at {DB_PATH}")


